{
  "hechos": [
    {
      "id": "H1",
      "texto": "El Festival de la Cosecha no se realizará este año.",
      "tipo": "dato",
      "paginas": ["P1", "P2", "P3", "P4"]
    },
    {
      "id": "H2",
      "texto": "Una plaga de gusano cogollero dañó buena parte del maíz.",
      "tipo": "dato",
      "paginas": ["P1", "P2", "P3", "P4"]
    },
    {
      "id": "H3",
      "texto": "El festival reunía cada año a unos 25.000 visitantes.",
      "tipo": "dato",
      "paginas": ["P1", "P4"]
    },
    {
      "id": "H4",
      "texto": "Unas 25.000 personas visitaban el festival en cada edición.",
      "tipo": "dato",
      "paginas": ["P1", "P3"]
    },
    {
      "id": "H5",
      "texto": "La suspensión fue ordenada por la Alcaldía de Santa Brígida.",
      "tipo": "atribucion",
      "paginas": ["P4"]
    },
    {
      "id": "H6",
      "texto": "Wilson Avendaño, integrante de la junta comunal del barrio Villa Nueva, contó a Voz del Valle que los hoteles empezaron a recibir cancelaciones.",
      "tipo": "atribucion",
      "paginas": ["P3"]
    },
    {
      "id": "H7",
      "texto": "Yolanda Ospina, comerciante del barrio El Carmen, contó a El Faro Regional que los artesanos ya habían comprado los materiales para sus puestos.",
      "tipo": "atribucion",
      "paginas": ["P1"]
    },
    {
      "id": "H8",
      "texto": "Andrés Avendaño, comerciante del barrio La Floresta, contó a Noticias Altiplano que la banda del colegio llevaba meses ensayando para el desfile.",
      "tipo": "atribucion",
      "paginas": ["P4"]
    },
    {
      "id": "H9",
      "texto": "En la vereda El Bosque, la asociación de productores contó 323 hectáreas afectadas.",
      "tipo": "dato",
      "paginas": ["P2"]
    },
    {
      "id": "H10",
      "texto": "En la vereda San José, la asociación de productores contó 315 hectáreas afectadas.",
      "tipo": "dato",
      "paginas": ["P3"]
    },
    {
      "id": "H11",
      "texto": "En la vereda Primero de Mayo, la asociación de productores contó 101 hectáreas afectadas.",
      "tipo": "dato",
      "paginas": ["P4"]
    },
    {
      "id": "H12",
      "texto": "En la vereda Santa Rita, la asociación de productores contó 43 hectáreas afectadas.",
      "tipo": "dato",
      "paginas": ["P1"]
    }
  ]
}
